  function portrait(kind,options={}){const player=options.player??(['cat','sword'].includes(kind)||(kind==='feiye'&&heroId()==='sovereign')),p=game?.state.player||{hp:60,maxHp:60},stage=options.previewStage||damageStage(p.hp,p.maxHp),src=player?(heroSources(kind)[stage]||images[kind]):images[kind],hp=options.previewStage?({normal:60,wounded:30,critical:15})[stage]:p.hp,maxHp=options.previewStage?60:p.maxHp;return `<div class="portrait ${player?'hero-portrait '+kind+'-portrait damage-'+stage:''}" data-portrait="${kind}" ${player?`data-hp="${hp}" data-max-hp="${maxHp}" data-damage-stage="${stage}" ${options.previewStage?`data-preview-stage="${stage}"`:''}`:''}>${kind==='sword'?(YokaiArt.sword||swordFallback()):(YokaiArt[kind]||YokaiArt.paper)}${src&&!src.startsWith('__')?`<img src="${esc(src)}" alt="${esc(names[kind]||kind)}${player?' · '+stageNames[stage]:''}" onload="this.parentElement.classList.add('portrait-image-ready')" onerror="this.parentElement.classList.add('image-failed')">`:''}${player?`<span class="damage-stage-label" ${stage==='normal'?'hidden':''}>${stageNames[stage]}</span>`:''}</div>`;}
