  function syncPlayerAppearance(player){for(const root of app.querySelectorAll('[data-combatant="player"] .hero-portrait')){const previous=root.dataset.damageStage,stage=damageStage(player.hp,player.maxHp),kind=root.dataset.portrait,src=heroSources(kind)[stage]||images[kind];root.dataset.hp=String(player.hp);root.dataset.maxHp=String(player.maxHp);root.dataset.damageStage=stage;for(const id of ['normal','wounded','critical'])root.classList.toggle('damage-'+id,id===stage);const image=root.querySelector(':scope > img');if(image&&src&&image.getAttribute('src')!==src){root.classList.remove('image-failed','portrait-image-ready');image.src=src;}if(image)image.alt=names[kind]+' · '+stageNames[stage];const label=root.querySelector('.damage-stage-label');if(label){label.hidden=stage==='normal';label.textContent=stageNames[stage];}if(previous&&previous!==stage){root.dataset.stageChanged=stage;const mark=fx('damage-transition','player',`<span>${stage==='normal'?'重新稳住气息':stage==='wounded'?'衣染战痕':'命火未熄'}</span>`);setTimeout(()=>{mark.remove();delete root.dataset.stageChanged;},motionMode==='fast'?150:750);}}}
