  const relics=ids=>ids.map(id=>`<button class="relic ${treasureIds.includes(id)?'treasure':''}" data-action="relics" data-relic="${id}" title="${esc(RELICS[id]?.text)}"><i>${esc(relicGlyphs[id]||'宝')}</i>${esc(RELICS[id]?.name||id)}</button>`).join('');
  function artFallback(id,glyph){const n=Number(String(id).replace(/\D/g,''))||String(id).length,hue=(n*37+23)%360;return `<svg viewBox="0 0 400 240" aria-hidden="true"><defs><radialGradient id="art-${esc(id)}"><stop stop-color="hsl(${hue},32%,36%)"/><stop offset="1" stop-color="#112427"/></radialGradient></defs><rect width="400" height="240" fill="url(#art-${esc(id)})"/><g stroke="#d5ba7e" fill="none" opacity=".5"><circle cx="200" cy="120" r="${65+n%18}"/><path d="M${40+n%40} 200 Q200 ${-10-n%20} ${355-n%35} 200 M65 45 L335 195 M65 195 L335 45"/><ellipse cx="200" cy="120" rx="105" ry="${45+n%40}" transform="rotate(${n*13} 200 120)"/></g><text x="200" y="148" fill="#eed9b0" text-anchor="middle" font-family="serif" font-size="79">${esc(glyph||'契')}</text></svg>`;}
