  function showPreview(el){if(!el||window.uiBusy||innerWidth<800||modal?.kind==='card-detail')return;const id=el.dataset.id;if(!CARDS[id])return;hidePreview();previewTimer=setTimeout(()=>{if(!el.isConnected)return;const box=document.createElement('aside');box.id='card-preview';box.className='card-preview';box.setAttribute('aria-hidden','true');box.innerHTML=cardMarkup(id,'detail');document.body.append(box);const r=el.getBoundingClientRect(),w=290,h=Math.min(490,innerHeight-35);box.style.width=w+'px';box.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))+'px';box.style.top=Math.max(12,Math.min(innerHeight-h-12,r.top-h-15))+'px';},260);}

