  function cardCategory(c){return ({mark:'猎印',combo:'连段',blood:'血契',guard:'守势',basic:'基础',soul:'魂息',echo:'魂息',frost:'霜寒',sword:'剑意',ice:'霜寒',blade:'剑意'})[c.category]||c.category||c.archetype||(c.text.includes('标记')?'标记':c.text.includes('生命')?'血契':c.text.includes('本回合')||c.text.includes('连续')?'连段':c.attack?'攻击':'守势');}
