    const id=typeof card==='string'?card:card.id,uid=typeof card==='string'?id:card.uid,c=CARDS[id];if(!c)return '';
    const bad=(mode==='hand'&&(window.uiBusy||game.state.battle.phase!=='player'||c.cost>game.state.battle.energy))||(mode==='reward'&&game.state.reward?.relicPending);
