    return `<${tag} class="card ${c.attack?'attack':''} ${c.exhaust?'exhaust':''} ${selected===uid?'selected':''} rarity-${esc(c.rarity||'common')} ${mode==='detail'?'detail-card':''}" data-id="${id}" data-preview="true" ${!action?'tabindex="0"':''} ${action?`data-action="${action}" data-card="${esc(uid)}" ${bad?'disabled':''} aria-label="${esc(c.name)}，${c.cost} 灵力。${esc(c.text)}"`:''}><div class="card-top"><span class="cost">${c.cost}</span><h4>${esc(c.name)}</h4></div><div class="card-traits"><span>${esc(cardCategory(c))}</span><span>${esc(rarity(c))}</span><span class="card-class">${id.startsWith('F')?'归月':id.startsWith('S')?'剑修':'刺客'}</span></div>${picture('cards',id,c.sigil||(id.startsWith('F')?'魂':id.startsWith('S')?'剑':sigils[Number(id.slice(1))-1])||c.name[0],`${c.name}独立画卡`,'card-art')}<p>${esc(c.text)}</p><div class="card-foot"><span>${c.attack?'攻击':c.target?'咒术':'技法'}${c.exhaust?' · 消耗':''}</span><span>${mode==='reward'?(game.state.reward?.relicPending?'先选一件珍藏':'选择入组'):mode==='remove'?'移除此实例':mode==='hand'?(bad?(window.uiBusy?'结算中':c.cost>game.state.battle.energy?'灵力不足':'敌人回合'):c.target?(selected===uid?'再点取消':'点击后选敌'):'点击使用'):id}</span></div></${tag}>`;
